&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Pourquoi rejoindre Capco?&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Capco est un cabinet de conseil international, spécialisé dans les services financiers.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;Fondé en 1998, le cabinet compte aujourd’hui plus de 7 000 collaborateurs dans 36 bureaux à travers le monde, dont 160 à Paris.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Challenger reconnu face aux grands noms du conseil, Capco se distingue par sa double expertise métier et technologique, au service de la stratégie comme de l’exécution.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Notre promesse : accompagner la transformation de nos clients dans un monde en constante mutation réglementaire, technologique et opérationnelle.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nous intervenons à l’intersection du business, de la réglementation et de la tech, en mobilisant des équipes pluridisciplinaires, expérimentées et engagées.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nos marqueurs distinctifs :&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Une spécialisation sectorielle forte&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nous apportons à nos clients une compréhension approfondie de leurs enjeux métiers, en particulier dans la banque, les marchés de capitaux et l’énergie.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Une approche collaborative et sur mesure&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nous intégrons les équipes clients, adaptons nos méthodes à leur culture et co-construisons des solutions concrètes et opérationnelles.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;L’excellence comme exigence&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;Notre ambition est d’obtenir des résultats mesurables et durables pour nos clients et de toujours viser la valeur ajoutée.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Un esprit “One Capco”&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nos équipes collaborent à l’échelle internationale pour mobiliser les meilleures expertises et partager les bonnes pratiques.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Une culture entrepreneuriale et inclusive&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;L’innovation, l’initiative et le mérite sont au cœur de notre modèle. Nous valorisons les idées, la diversité et le progrès collectif.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
